READINGS=[
dict(title='The map cabinet',text='''The library’s oldest maps lived in a locked cabinet. Their brown edges and unfamiliar place names made them look important, but nobody seemed to know what to do with them. When Tara asked to borrow one for a geography project, the librarian was reluctant. She had spent years protecting the collection from damp, dust and careless fingers. A schoolbag seemed to her a more immediate danger than any of these.

Tara did not argue that the maps belonged to everybody. Instead, she proposed a supervised afternoon at the long library table. She would use clean paper beneath each sheet, make notes in pencil and return every map before leaving. The librarian agreed to a temporary arrangement, watching from her desk as six pupils compared a map printed fifty years earlier with a recent one.

At first they copied obvious changes: a housing estate where woodland had stood, a broad road replacing a narrow lane, a stream now marked as a drain. Then a question interrupted their neat columns. Why had the older map shown a footpath ending beside an apparently empty field? A retired railway worker who visited the library supplied an answer. The field had once hosted a weekly market; people had walked there from the station. The path had survived on paper after the market itself disappeared.

The pupils began interviewing residents. Their work became meticulous: a memory was labelled as a memory, a date checked against records, an uncertainty left visible. Different accounts sometimes disagreed. Rather than choose the most colourful version, they recorded both and looked for another source. Their display eventually included two maps, short interviews and questions they had not yet settled.

On the final afternoon the librarian stood before the display for a long time. The maps were neither damaged nor perfectly explained. They had become useful, and their unanswered details had made people look more carefully. She kept the cabinet locked, but added a notice inviting supervised use. Protection, she decided, need not mean permanent silence.''',
vocab=[('reluctant','unwilling','careless','delighted','confident'),('meticulous','very careful','extremely quick','unusually loud','easily discouraged')],opposite=('permanent','temporary'),
questions=[('What safeguards did Tara propose, and why did they persuade the librarian?','Supervision at a table; clean paper/pencil and same-day return; these addressed handling risk instead of dismissing the need for protection.'),('Explain how the footpath changed the pupils’ investigation.','It raised a question rather than a simple map comparison; the railway worker connected it with a lost market; pupils turned to residents and records.'),('How did the pupils deal with conflicting memories, and what did the librarian learn?','They retained differing accounts; checked other sources and marked uncertainty; careful use could protect the collection’s value rather than threaten it.')],
summaryPrompt='Summarise how the pupils used and investigated the old maps responsibly.',summary='The pupils negotiated supervised handling, compared old and recent maps, and investigated unexplained changes through interviews and records. They distinguished memories from verified dates, retained conflicting accounts and marked uncertainty. Their display included evidence and unresolved questions, showing that careful use could preserve the maps’ value.'),
dict(title='The missing stop',text='''For eleven years the afternoon bus had stopped beside a banyan tree on the edge of the village. There was no signboard. A stone bench, a tea stall and the passengers’ habit were enough to identify the place. When roadworks began, the transport office announced that the stop would move half a kilometre uphill for a month. Most of the regular passengers accepted the change without complaint.

On the first afternoon at the new stop, Arun noticed that Mrs D’Souza was missing. She usually boarded with a cloth bag of vegetables and asked him whether his examinations had begun. At home he mentioned her absence. His father pointed out that an uphill walk which took a student five minutes might be difficult for somebody using a walking stick. Arun had thought of the change as a distance, not as an effort.

The next day he walked the route before school. The temporary stop stood beside a busy bend, with no bench and little space away from traffic. He took photographs, but his teacher advised him that a persuasive complaint needed more than alarming pictures. He counted passengers, spoke to the driver and asked the road supervisor where a safe stopping place might be possible. The supervisor explained that the old location could not remain open while a trench crossed its approach.

Arun’s first suggestion, to stop directly outside Mrs D’Souza’s house, was rejected. The road there was too narrow for a bus to wait safely. A second suggestion was more practical: the level entrance of the community hall, reached without crossing the works, had room for passengers to stand clear of vehicles. The hall committee agreed to provide two chairs during bus hours.

The transport office approved the proposal after a trial. Nobody described it as a victory. The driver still had to adjust his timing and passengers still walked farther than before. But Mrs D’Souza returned to the bus. Arun discovered that a useful solution could be modest, inconvenient and better than the alternatives at the same time.''',
vocab=[('persuasive','convincing','lengthy','angry','secret'),('modest','limited in scale','impossible','carelessly planned','extravagant')],opposite=('permanent','temporary'),
questions=[('Why had Arun initially misunderstood the difficulty caused by the moved stop?','He measured the change as a short distance; assumed his own easy walk applied to everyone; had not considered the uphill effort for someone using a stick.'),('What information did Arun collect beyond photographs, and why did it matter?','Passenger counts; driver’s view; supervisor’s safety constraints. These supported a workable request and explained why the old site could not continue.'),('Compare Arun’s first and final proposals.','A stop outside the house was narrow/unsafe; the hall entrance was level and offered safe standing space; chairs and a trial made the revised proposal practical.')],
summaryPrompt='Summarise the steps Arun took to secure a safer temporary bus stop.',summary='Arun inspected the moved stop, documented conditions, counted passengers and consulted the driver and road supervisor. After a narrow roadside location was rejected, he proposed the level community-hall entrance. The committee supplied chairs, and the transport office approved the site after a trial.'),
dict(title='An unexpected repair',text='''The radio had belonged to Mira’s grandmother. It no longer worked, but her father kept it on a shelf because its wooden case reminded him of evenings when the family gathered around it. Mira liked the smooth tuning knob. During a holiday she took the radio to a repair shop, expecting either a quick repair or an equally quick refusal.

The shopkeeper, Mr Karim, did neither. He asked what she wanted restored: a working radio, the appearance of the object, or the memories attached to it. Mira thought the distinction unnecessary. A repaired radio would surely provide all three. He opened the back and showed her a brittle wire, a missing component and a crack in a part that was no longer manufactured. A modern replacement could make the set play, but it would not be an exact reconstruction.

Mira carried the radio home to discuss the choice. Her father was less concerned about authenticity than she expected. He wanted the family to be able to hear it again. Her grandmother, however, remembered the radio’s original limitations as clearly as its pleasures: the uncertain reception, the sudden whistles, the need to remain still while somebody adjusted the aerial. She laughed at the idea that the old days had sounded perfect.

They chose a reversible repair. Mr Karim installed a small modern receiver inside without cutting the old case. He labelled the new parts and placed the disconnected originals in a separate box. Mira kept a record of the alterations. The radio’s scratches remained, including one beside the knob that her father recognised immediately.

When the family finally switched it on, a clear voice filled the room. Her grandmother listened, then turned the volume down. For a moment Mira thought something was wrong. “Now we can hear one another too,” she said. The repair had not returned them to an earlier evening. It had given an old object a new role among people whose memories of it were different, and whose conversation mattered more than perfect reception.''',
vocab=[('brittle','easily broken','very flexible','newly polished','heavily soaked'),('reversible','able to be undone','impossible to record','designed to be hidden','extremely expensive')],opposite=('connected','disconnected'),
questions=[('Why did Mr Karim ask what the family wanted restored?','Function, appearance and memories were distinct aims; unavailable parts prevented exact reconstruction; different choices would preserve different qualities.'),('How did the grandmother complicate Mira’s view of the past?','She remembered reception problems and whistles; did not describe old sound as perfect; valued listening and conversation over an idealised restoration.'),('What made the chosen repair responsible and reversible?','No cutting of the case; new parts labelled; originals kept and changes recorded. Scratches and identifiable marks were preserved.')],
summaryPrompt='Summarise how the family decided on and carried out the radio repair.',summary='The family discussed whether function or exact reconstruction mattered more. They chose a modern receiver installed without cutting the case. The repairer labelled new components and kept original parts separately; Mira recorded the alterations. Existing marks remained, allowing renewed use without pretending the radio was unchanged.'),
dict(title='The water notebook',text='''The caretaker was blamed first. Water had overflowed from the school tank twice in one week, and somebody said he must have forgotten the pump. Before the principal questioned him, the science club asked permission to observe the system for several days. The principal agreed, provided that they did not touch electrical equipment or interfere with the caretaker’s work.

The club began with a notebook. Pupils recorded the times when the pump started and stopped, whether classrooms were occupied, and whether taps were running. Their first pages were untidy. One observer wrote “late morning” instead of a time; another described the tank as “almost full” without saying how that had been judged. The teacher asked them to record what they actually saw and distinguish it from an explanation.

By the fourth day a pattern emerged. Overflow did not follow an unusually long pumping period. It followed a sudden interruption in water use during lunch, when the usual sound from the pipes ceased. The automatic level switch sometimes remained stuck, and the caretaker had been relying on that familiar sound as an extra warning. A fault in the system and a change in routine had combined to defeat two safeguards.

An electrician replaced the switch. The club suggested a visible indicator in the caretaker’s room and a temporary manual log while its reliability was checked. They also noticed a dripping tap, but the principal refused to let the smaller discovery obscure the main result. The investigation had not shown that nobody was responsible. It had shown that responsibility could not be assigned fairly before the facts were understood.

At assembly, the club presented both its findings and its early mistakes. The caretaker stood beside them while they explained how he had helped test their account. The notebook went into the laboratory cupboard. It contained no dramatic accusation, only times, observations, corrections and a conclusion that was stronger because the pupils had been willing to revise it.''',
vocab=[('emerged','became apparent','was concealed','was destroyed','was postponed'),('obscure','hide or make unclear','confirm precisely','repair quickly','describe briefly')],opposite=('permanent','temporary'),
questions=[('What limits were placed on the pupils’ investigation, and why were they sensible?','No electrical handling; no interference with caretaker; observations could proceed safely while qualified staff handled the equipment.'),('Explain the two failed safeguards identified by the investigation.','Level switch stuck; caretaker used pipe sound as a warning; lunchtime interruption removed the expected sound, so the fault went unnoticed.'),('How did the club make its conclusion more reliable?','Used recorded times and direct observations; corrected vague records; tested explanations with caretaker/electrician and acknowledged early mistakes.')],
summaryPrompt='Summarise how the club investigated and helped prevent the tank overflow.',summary='The club logged pump times, use and direct observations, improving initially vague records. It linked overflow to a sticking switch and a lunchtime interruption that removed an informal sound warning. An electrician replaced the switch; the pupils proposed an indicator and temporary log, and openly reported their corrections.'),
dict(title='The first rehearsal',text='''The first rehearsal was a failure that sounded like a success. Every actor knew the lines. Each voice was loud enough to reach the back row, and not one speech was omitted. Yet when the curtain fell, the director said the scene had never really begun. The pupils looked at one another, certain that she had overlooked their effort.

She asked them to repeat the scene without speaking. They were to listen for entrances, watch one another and react only when something had changed. Suddenly there were long, awkward gaps. An actor crossed the stage before anyone had given a reason to follow. A chair was moved into the path of a character who was meant to leave. Without the words, their lack of attention became visible.

Leela, who had the longest part, was embarrassed. She had practised alone so often that she heard the other speeches only as signals announcing her next one. During the second rehearsal she missed an entrance because she was genuinely watching another actor. This time the director did not stop them. The actor waiting at the door found a plausible reason to remain there until Leela noticed, and the scene continued.

They began keeping a short record after each practice: where attention had broken, what an action had changed and which problem could be solved without rushing. The exercise did not make mistakes disappear. It made the pupils less anxious to conceal them. A temporary setback could become a useful question for the next rehearsal.

On performance night a prop rolled beneath a bench. The audience saw one actor retrieve it and another adjust her movement to make room. The exchange looked natural because it was a response rather than a remembered instruction. Afterwards, Leela’s friends praised her speeches. She thanked them, but privately remembered the moment when she had stopped waiting for her turn and started noticing the whole scene.''',
vocab=[('plausible','believable','astonishing','inaudible','unnecessary'),('conceal','hide','repeat','announce','measure')],opposite=('permanent','temporary'),
questions=[('Why did the director call the first rehearsal unsuccessful despite accurate speeches?','Actors recited correctly but did not respond to each other; actions lacked motivation; the scene lacked connected interaction.'),('What did the silent exercise reveal?','Awkward gaps; premature crossing and obstructive chair movement; dependence on lines rather than attention to events.'),('What change in Leela helped the final performance?','She began observing fellow actors; accepted recoverable mistakes; responded naturally to the missing prop instead of rigidly following memorised instructions.')],
summaryPrompt='Summarise the methods that improved the pupils’ performance.',summary='The director replaced recitation with a silent exercise exposing inattentive actions. Pupils practised listening, watching and responding to changes. They recorded breaks in attention and treated mistakes as questions for later rehearsal. This made them able to adjust naturally when a prop rolled away during the performance.'),
dict(title='A hill path',text='''The proposed path across the hillside looked excellent on the planner’s drawing. It was shorter than the winding track people already used and would reduce the walk to the health centre. The village committee welcomed it. Only the guide who led school walks asked why the existing track turned so far to the east before climbing.

At the planning meeting his question seemed like resistance to improvement. The old route was inconvenient, and everybody knew it. Rather than repeat the objection, he invited two committee members to walk the direct line after rain. Within minutes their shoes were sinking into soft ground. A small channel, invisible in dry weather, had become a stream. Higher up, loose stones crossed the slope where water had washed away the soil.

The guide did not claim that the older path was perfect. It was narrow in places and difficult for an injured person. He explained that it followed firmer ground, approached a crossing at a shallower angle and avoided the steepest patch. Its apparent detour preserved information that the drawing had not included. The committee asked the planner to walk both routes before revising the scheme.

The final proposal widened part of the existing track, added a handrail at one steep section and made a short new connection to the centre. It saved less distance than the first design, but needed fewer retaining works and was safer in wet weather. A temporary marker was placed where the new section began so that users could report difficulties before permanent surfacing.

At the opening there was no claim that local knowledge had defeated expert planning. The planner’s measurements had made several improvements possible. The guide’s experience had revealed the conditions those measurements needed to address. Both were necessary. What changed was the committee’s willingness to treat a troublesome question as information rather than disloyalty.''',
vocab=[('detour','a longer indirect route','a dangerous vehicle','a sudden argument','a private boundary'),('retaining','holding back or supporting','decorating','removing completely','measuring twice')],opposite=('permanent','temporary'),
questions=[('What did the wet-weather walk reveal that the first drawing missed?','Soft ground; a seasonal water channel; loose stones/eroded steep ground along the apparently shorter route.'),('Why did the existing route turn away before climbing?','It followed firmer ground; reached a safer/shallow crossing; avoided the steepest patch. Its length reflected practical constraints.'),('How did the final scheme combine two kinds of knowledge?','Local experience identified wet-weather hazards; expert measurements supported widening, rail and connection design; a trial marker allowed further user feedback.')],
summaryPrompt='Summarise why the path scheme changed and what the revised proposal included.',summary='A wet-weather inspection exposed soft ground, a seasonal stream and unstable stones on the direct route. The older track avoided these hazards. The revised scheme widened that track, added a handrail and a short connection, while temporary marking allowed users to report problems before permanent surfacing.'),
dict(title='A borrowed telescope',text='''The telescope arrived in a long padded case, accompanied by instructions that seemed more complicated than the instrument. The astronomy club had borrowed it for one evening. Its members wanted photographs of the moon to display at assembly, and the clearest image would, they imagined, be the measure of a successful event.

Cloud covered the sky before sunset. While the pupils waited, their guest, an amateur observer named Ms Sen, asked them to describe what they expected to see. Several spoke confidently of colours they had seen in space photographs. She explained that published images could combine long exposures, filters and processing. Looking through an eyepiece was a different experience, not necessarily a poorer one.

When the clouds thinned, the first view lasted only a few seconds. A pupil called it disappointing. The moon looked small, and the telescope shook whenever somebody leaned against the table. Ms Sen lowered the magnification, moved the instrument to firmer ground and asked each viewer to find one feature near the boundary between light and shadow. At that boundary, low sunlight made the relief easier to distinguish.

The pupils started comparing observations. One described a dark oval; another noticed a bright edge beside it. They made quick sketches in a notebook, not for display but to check whether they had seen the same feature. A temporary clearing gave them a second chance to look. This time nobody hurried to photograph the whole view. They knew what they wanted to examine.

Their assembly presentation contained one imperfect photograph, several observations and an explanation of why the first attempt had failed. The telescope had not brought distant objects conveniently close. It had shown how movement, expectation and the choice of a question affect seeing. The club returned it the next morning with the instructions carefully folded. They now regarded the least glamorous pages as part of the instrument.''',
vocab=[('relief','differences in surface height','a feeling of boredom','an artificial colour','a printed label'),('glamorous','excitingly attractive','technically exact','difficult to fold','completely useless')],opposite=('permanent','temporary'),
questions=[('Why did Ms Sen discuss published space photographs before observation began?','To examine expectations; explain exposure/filter/processing differences; distinguish an eyepiece view from a published image without calling it inferior.'),('What adjustments improved observation?','Lower magnification; firmer support/ground; attention to a feature near the light-shadow boundary where relief was clearer.'),('How did the final presentation reflect learning rather than conceal failure?','Included an imperfect photo; shared observations and reasons for initial failure; explained how support, expectations and a focused question changed seeing.')],
summaryPrompt='Summarise how Ms Sen helped pupils improve their astronomical observations.',summary='Ms Sen clarified how published photographs differ from eyepiece views. She reduced magnification, stabilised the telescope and directed attention to a feature near the light-shadow boundary. Pupils compared notes and revisited the same feature during a clearing, replacing the demand for a perfect photograph with focused observation.'),
dict(title='The ferry ledger',text='''The ferry office’s ledger recorded numbers, not stories: passengers, fares, fuel and the time of each crossing. When a temporary reduction in service was proposed, a district officer used the figures to identify the least crowded journey. Cancelling that crossing appeared a reasonable way to save money without seriously affecting the route.

The ferryman, Joseph, asked to keep an additional record for a fortnight. He did not dispute the passenger count. The small early crossing often carried fewer than ten people, while later ones were full. But he knew that the people on the quiet journey rarely had the freedom to take another. Some worked at the hospital, and two travelled onward by a connecting bus which left soon after the ferry arrived.

Joseph’s new record contained occupations and onward connections, collected only with passengers’ consent. He did not write private details. He also recorded tides, delays and the number of people who returned without boarding when a crossing was late. The figures revealed an awkward fact: the apparently least useful journey supported activities whose value was not represented by its fares.

The officer visited the landing. She asked whether the ferry could carry goods on the early journey to improve its income. Local traders agreed to a trial with small deliveries that did not delay passengers. The timetable remained, although another quiet crossing was combined with a nearby service. Nobody received everything requested.

Joseph continued the ledger. He did not believe that numbers had become less important. They had become more informative because someone had asked what they omitted. When the trial was reviewed, the officer thanked him for the extra columns. He pointed to the original ones. Without those records, he said, they would not have known where a question needed to be asked.''',
vocab=[('consent','permission','payment','an accusation','confusion'),('omitted','left out','calculated','confirmed','delivered')],opposite=('permanent','temporary'),
questions=[('Why did the officer initially choose the early crossing for cancellation?','Low passenger count; lower income/apparent utilisation; saving seemed possible with limited route impact.'),('What did Joseph’s extra columns reveal?','Hospital work/onward buses; limited alternatives; late passengers returning without boarding. Fare counts alone omitted the crossing’s supporting role.'),('How was the final decision a compromise?','Early timetable retained; goods trial improved use without delaying passengers; another quiet crossing combined with a nearby service.')],
summaryPrompt='Summarise Joseph’s investigation and its effect on the service decision.',summary='Joseph kept additional records of work journeys, connections and missed crossings with passenger consent. These showed that the lightly used ferry supported essential activities with few alternatives. After visiting, the officer retained it and trialled goods deliveries, while combining another quiet crossing with a nearby service.'),
dict(title='The seed exchange',text='''The seed exchange began with a table outside the community hall and a hand-painted request: bring what you can spare, take only what you can grow. The organisers expected a pleasant morning of trading. Instead, the first disagreement began before the first packet changed hands. Two gardeners used the same local name for different plants.

One of them insisted that the label was wrong. The other unfolded a paper containing a description in her mother’s handwriting. The argument might have ended with somebody leaving if a volunteer had not suggested keeping both names and adding a description. The packet acquired an unusually long label, including the shape of the fruit and the village from which the seed had come.

Other problems followed. Some seeds had been saved after cross-pollination; their next crop might not resemble the parent exactly. Others had been stored in a damp cupboard. An experienced grower explained that certainty could not be added to a packet by writing confidently on it. The organisers made room for notes about storage, age and uncertainty, and stopped calling every locally saved seed an unchanged old variety.

By noon the exchange looked less tidy than planned. A temporary notice invited recipients to report what grew, and pupils offered to collect those accounts at the next meeting. A gardener who had initially brought nothing took a small packet after describing the sunny patch beside her kitchen. Another returned a packet because she realised that its plant would need more space than she had.

The exchange did not guarantee a harvest. Some seeds would fail, and some labels would be corrected. Its success was a new habit of sharing useful limits along with useful material. The longest label remained on the table until the end. When its owner finally took it home, she copied both names rather than choosing a winner.''',
vocab=[('resemble','look like','damage','replace completely','grow faster than'),('recipients','people receiving something','people selling tools','people refusing help','people writing rules')],opposite=('permanent','temporary'),
questions=[('How was the first naming dispute resolved?','Both local names retained; descriptive fruit/origin information added; no forced declaration that one gardener’s family name was wrong.'),('Why were notes about uncertainty important?','Cross-pollination could change offspring; damp storage/age affected viability; confident labels could not guarantee unchanged varieties or germination.'),('What did responsible participation require beyond giving or taking packets?','Describe available growing conditions; accept limited quantities suitable for space; report outcomes/corrections so later users had better information.')],
summaryPrompt='Summarise how the organisers made the seed exchange more informative and responsible.',summary='They retained different local names and added descriptions and origins. Notes recorded storage, age and uncertainty about offspring or germination. Recipients matched seeds to their growing space and were invited to report results, allowing labels to be corrected instead of treating confident claims as guarantees.'),
dict(title='The quiet bench',text='''A bench stood under the only large tree in the station forecourt. When a café sought permission to put tables there, the proposal described the area as unused space. The station manager almost signed the temporary licence. Then the cleaner asked whether the word “unused” meant nobody had paid for it or nobody had sat there.

For three days she kept a simple count during her breaks. She saw delivery workers waiting between jobs, a father feeding a child, passengers eating food brought from home and an elderly man who seemed to come only to watch the trains. None stayed long enough to attract attention. Their separate pauses did not look like an organised use, but together they occupied most of the day.

The manager asked the café owner to discuss a different arrangement. The owner pointed out that a business paid rent and employed people; a bench produced no direct income. The cleaner agreed, but asked what would happen to somebody who could not afford a drink. The question was not whether the café deserved space. It was whether every useful place had to require a purchase.

They measured the forecourt together. By moving a storage bin and narrowing an unnecessarily wide advertising stand, they found room for two café tables without removing the public bench or blocking the path used by wheelchair passengers. The licence specified the table positions and kept the bench outside the café’s customer area.

The elderly man returned the next week. He looked at the new tables, sat down and opened a paper parcel. Nobody asked him to order anything. The cleaner’s count had not measured comfort, dignity or the relief of resting without explanation. It had simply made an ordinary use visible long enough for those deciding about the space to acknowledge it.''',
vocab=[('forecourt','open area in front of a building','an upstairs room','a railway carriage','a legal document'),('acknowledge','recognise or accept','price competitively','remove immediately','record secretly')],opposite=('permanent','temporary'),
questions=[('What distinction did the cleaner introduce about “unused” space?','Lack of paid/commercial use differs from lack of public use; people used the bench in brief separate visits; those visits were easily overlooked.'),('How did the café owner and cleaner define value differently?','Owner stressed rent/jobs/direct income; cleaner stressed accessible rest without purchase; both recognised the café’s legitimate need for space.'),('What made the final arrangement workable?','Storage bin moved; advertising stand narrowed; table positions specified while keeping bench public and wheelchair path clear.')],
summaryPrompt='Summarise how the bench was retained while allowing the café to expand.',summary='The cleaner recorded varied short visits, showing that the bench was used despite producing no income. Discussion recognised both commercial and public needs. Moving storage and reducing an advertising stand created room for café tables, while licence conditions protected the public bench and accessible passage.'),
]

def make_bank():
    result=[]
    for i,r in enumerate(READINGS):
        assert all(word.lower() in r['text'].lower() for word,*_ in r['vocab'])
        assert r['opposite'][1] in r['text']
        assert len(r['summary'].split())<=50
        qs=[]; answers=[]
        for j,(word,correct,*wrong) in enumerate(r['vocab'],1):
            options=[correct]+wrong
            from .common import rng
            rng('reading-vocabulary',i*2+j).shuffle(options)
            qs.append(f'(i{chr(96+j)}) Choose the meaning of “{word}” as used in the passage: '+ '; '.join(f'{"ABCD"[k]}. {x}' for k,x in enumerate(options))+' [1]')
            answers.append(f'(i{chr(96+j)}) {"ABCD"[options.index(correct)]}. {correct}.')
        qs.append(f'(ii) Find a word in the passage opposite in meaning to “{r["opposite"][0]}”. [1]');answers.append('(ii) '+r['opposite'][1]+'.')
        for j,(prompt,answer) in enumerate(r['questions'],1):qs.append(f'(iii{chr(96+j)}) {prompt} [3]');answers.append(f'(iii{chr(96+j)}) {answer} Award one mark per distinct relevant point, up to 3.')
        qs.append('(iv) '+r['summaryPrompt']+' Use not more than 50 words. [8]');answers.append('(iv) Model summary ('+str(len(r['summary'].split()))+' words): '+r['summary']+' Award content 6 and concise connected expression 2; accept equivalent relevant wording within the limit.')
        result.append(item('Reading · 10 passages',r['text']+'\n\n'+'\n'.join(qs),'\n\n'.join(answers),20,id=f'english1-reading-{i+1:02}',section='Reading · 10 passages',title=r['title'],passage=r['text'],parts=[1,1,1,3,3,3,8]))
    return result
